import React, { useState, useEffect } from 'react';
import { Sun, Moon, Globe, Menu, X, ChevronDown } from 'lucide-react';

// Traductions pour le header
const translations = {
  en: {
    home: 'Home',
    about: 'About',
    services: 'Services',
    portfolio: 'Portfolio',
    contact: 'Contact',
    language: 'Language',
    theme: 'Theme',
    light: 'Light',
    dark: 'Dark',
    system: 'System',
    welcome: 'Welcome',
    getStarted: 'Get Started',
  },
  fr: {
    home: 'Accueil',
    about: 'À propos',
    services: 'Services',
    portfolio: 'Portfolio',
    contact: 'Contact',
    language: 'Langue',
    theme: 'Thème',
    light: 'Clair',
    dark: 'Sombre',
    system: 'Système',
    welcome: 'Bienvenue',
    getStarted: 'Commencer',
  },
  mg: {
    home: 'Fandraisana',
    about: 'Momba',
    services: 'Tolotra',
    portfolio: 'Portfolio',
    contact: 'Fifandraisana',
    language: 'Fiteny',
    theme: 'Teny',
    light: 'Mazava',
    dark: 'Maizina',
    system: 'Rafitra',
    welcome: 'Tonga soa',
    getStarted: 'Atombohy',
  },
};

const Header = () => {
  // États
  const [language, setLanguage] = useState('fr');
  const [darkMode, setDarkMode] = useState(false);
  const [mobileMenuOpen, setMobileMenuOpen] = useState(false);
  const [languageDropdownOpen, setLanguageDropdownOpen] = useState(false);
  const [themeDropdownOpen, setThemeDropdownOpen] = useState(false);

  // Navigation items
  const navItems = ['home', 'about', 'services', 'portfolio', 'contact'];

  // Initialiser le mode sombre au chargement
  useEffect(() => {
    // Vérifier les préférences système et le stockage local
    const storedTheme = localStorage.getItem('theme');
    const systemPrefersDark = window.matchMedia('(prefers-color-scheme: dark)').matches;

    if (storedTheme === 'dark' || (!storedTheme && systemPrefersDark)) {
      setDarkMode(true);
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }
  }, []);

  // Changer le mode sombre/clair
  const toggleDarkMode = () => {
    const newDarkMode = !darkMode;
    setDarkMode(newDarkMode);

    if (newDarkMode) {
      document.documentElement.classList.add('dark');
      localStorage.setItem('theme', 'dark');
    } else {
      document.documentElement.classList.remove('dark');
      localStorage.setItem('theme', 'light');
    }
  };

  // Changer de langue
  const changeLanguage = (lang) => {
    setLanguage(lang);
    setLanguageDropdownOpen(false);
    // Ici, vous pourriez déclencher un événement global ou utiliser un contexte
    // pour mettre à jour la langue dans toute l'application
  };

  // Changer le thème
  const changeTheme = (theme) => {
    if (theme === 'system') {
      localStorage.removeItem('theme');
      const systemPrefersDark = window.matchMedia('(prefers-color-scheme: dark)').matches;
      setDarkMode(systemPrefersDark);
      if (systemPrefersDark) {
        document.documentElement.classList.add('dark');
      } else {
        document.documentElement.classList.remove('dark');
      }
    } else {
      const newDarkMode = theme === 'dark';
      setDarkMode(newDarkMode);
      localStorage.setItem('theme', theme);
      if (newDarkMode) {
        document.documentElement.classList.add('dark');
      } else {
        document.documentElement.classList.remove('dark');
      }
    }
    setThemeDropdownOpen(false);
  };

  // Obtenir le texte traduit
  const t = (key) => translations[language][key] || key;

  return (
    <header className="sticky top-0 z-50 w-full border-b border-neutral-200 dark:border-neutral-800 bg-white/80 dark:bg-neutral-950/80 backdrop-blur-md transition-colors duration-300">
      <div className="container mx-auto px-4 sm:px-6 lg:px-8">
        <div className="flex items-center justify-between h-16">

          {/* Logo */}
          <div className="flex items-center space-x-2">
            <div className="h-10 w-10 rounded-full bg-gradient-to-r from-primary-500 to-secondary-500 flex items-center justify-center">
              <span className="font-bold text-white">L</span>
            </div>
            <span className="text-xl font-bold text-neutral-900 dark:text-white">
              Luxe<span className="text-primary-600 dark:text-primary-400">Design</span>
            </span>
          </div>

          {/* Navigation Desktop */}
          <nav className="hidden md:flex items-center space-x-1">
            {navItems.map((item) => (
              <a
                key={item}
                href={`#${item}`}
                className="px-4 py-2 rounded-lg text-neutral-700 dark:text-neutral-300 hover:text-primary-600 dark:hover:text-primary-400 hover:bg-primary-50 dark:hover:bg-primary-900/30 transition-all duration-200 font-medium"
              >
                {t(item)}
              </a>
            ))}
          </nav>

          {/* Actions: Langue, Thème, Bouton CTA */}
          <div className="flex items-center space-x-2">

            {/* Menu mobile burger */}
            <button
              onClick={() => setMobileMenuOpen(!mobileMenuOpen)}
              className="md:hidden p-2 rounded-lg text-neutral-700 dark:text-neutral-300 hover:bg-neutral-100 dark:hover:bg-neutral-800"
              aria-label="Menu"
            >
              {mobileMenuOpen ? <X size={24} /> : <Menu size={24} />}
            </button>

            {/* Sélecteur de langue */}
            <div className="relative">
              <button
                onClick={() => {
                  setLanguageDropdownOpen(!languageDropdownOpen);
                  setThemeDropdownOpen(false);
                }}
                className="flex items-center space-x-1 px-3 py-2 rounded-lg border border-neutral-200 dark:border-neutral-800 bg-white dark:bg-neutral-900 hover:bg-neutral-50 dark:hover:bg-neutral-800 transition-colors"
                aria-label={t('language')}
              >
                <Globe size={18} className="text-neutral-600 dark:text-neutral-400" />
                <span className="font-medium text-neutral-700 dark:text-neutral-300">
                  {language === 'en' ? 'EN' : language === 'fr' ? 'FR' : 'MG'}
                </span>
                <ChevronDown size={16} className="text-neutral-500" />
              </button>

              {/* Dropdown langue */}
              {languageDropdownOpen && (
                <div className="absolute right-0 mt-2 w-40 py-2 bg-white dark:bg-neutral-900 border border-neutral-200 dark:border-neutral-800 rounded-lg shadow-lg z-50">
                  <button
                    onClick={() => changeLanguage('en')}
                    className={`w-full text-left px-4 py-2 hover:bg-primary-50 dark:hover:bg-primary-900/30 transition-colors ${language === 'en' ? 'text-primary-600 dark:text-primary-400 font-medium' : 'text-neutral-700 dark:text-neutral-300'}`}
                  >
                    <div className="flex items-center space-x-2">
                      <span className="text-sm">🇺🇸</span>
                      <span>English</span>
                    </div>
                  </button>
                  <button
                    onClick={() => changeLanguage('fr')}
                    className={`w-full text-left px-4 py-2 hover:bg-primary-50 dark:hover:bg-primary-900/30 transition-colors ${language === 'fr' ? 'text-primary-600 dark:text-primary-400 font-medium' : 'text-neutral-700 dark:text-neutral-300'}`}
                  >
                    <div className="flex items-center space-x-2">
                      <span className="text-sm">🇫🇷</span>
                      <span>Français</span>
                    </div>
                  </button>
                  <button
                    onClick={() => changeLanguage('mg')}
                    className={`w-full text-left px-4 py-2 hover:bg-primary-50 dark:hover:bg-primary-900/30 transition-colors ${language === 'mg' ? 'text-primary-600 dark:text-primary-400 font-medium' : 'text-neutral-700 dark:text-neutral-300'}`}
                  >
                    <div className="flex items-center space-x-2">
                      <span className="text-sm">🇲🇬</span>
                      <span>Malagasy</span>
                    </div>
                  </button>
                </div>
              )}
            </div>

            {/* Sélecteur de thème */}
            <div className="relative hidden sm:block">
              <button
                onClick={() => {
                  setThemeDropdownOpen(!themeDropdownOpen);
                  setLanguageDropdownOpen(false);
                }}
                className="flex items-center space-x-1 px-3 py-2 rounded-lg border border-neutral-200 dark:border-neutral-800 bg-white dark:bg-neutral-900 hover:bg-neutral-50 dark:hover:bg-neutral-800 transition-colors"
                aria-label={t('theme')}
              >
                {darkMode ? (
                  <Moon size={18} className="text-neutral-600 dark:text-neutral-400" />
                ) : (
                  <Sun size={18} className="text-neutral-600 dark:text-neutral-400" />
                )}
                <ChevronDown size={16} className="text-neutral-500" />
              </button>

              {/* Dropdown thème */}
              {themeDropdownOpen && (
                <div className="absolute right-0 mt-2 w-40 py-2 bg-white dark:bg-neutral-900 border border-neutral-200 dark:border-neutral-800 rounded-lg shadow-lg z-50">
                  <button
                    onClick={() => changeTheme('light')}
                    className="w-full text-left px-4 py-2 flex items-center space-x-3 hover:bg-primary-50 dark:hover:bg-primary-900/30 transition-colors text-neutral-700 dark:text-neutral-300"
                  >
                    <Sun size={16} />
                    <span>{t('light')}</span>
                  </button>
                  <button
                    onClick={() => changeTheme('dark')}
                    className="w-full text-left px-4 py-2 flex items-center space-x-3 hover:bg-primary-50 dark:hover:bg-primary-900/30 transition-colors text-neutral-700 dark:text-neutral-300"
                  >
                    <Moon size={16} />
                    <span>{t('dark')}</span>
                  </button>
                  <button
                    onClick={() => changeTheme('system')}
                    className="w-full text-left px-4 py-2 flex items-center space-x-3 hover:bg-primary-50 dark:hover:bg-primary-900/30 transition-colors text-neutral-700 dark:text-neutral-300"
                  >
                    <div className="flex items-center">
                      <Sun size={14} className="mr-[-2px]" />
                      <Moon size={14} className="ml-[-2px]" />
                    </div>
                    <span>{t('system')}</span>
                  </button>
                </div>
              )}
            </div>

            {/* Bouton mode sombre/clair (version simple) */}
            <button
              onClick={toggleDarkMode}
              className="sm:hidden p-2 rounded-lg border border-neutral-200 dark:border-neutral-800 bg-white dark:bg-neutral-900 hover:bg-neutral-50 dark:hover:bg-neutral-800 transition-colors"
              aria-label={t('theme')}
            >
              {darkMode ? (
                <Moon size={20} className="text-neutral-600 dark:text-neutral-400" />
              ) : (
                <Sun size={20} className="text-neutral-600 dark:text-neutral-400" />
              )}
            </button>

            {/* Bouton CTA */}
            <button className="hidden sm:block px-4 py-2 bg-gradient-to-r from-primary-500 to-secondary-500 hover:from-primary-600 hover:to-secondary-600 text-white font-medium rounded-lg transition-all duration-300 hover:shadow-lg hover:shadow-primary-500/25">
              {t('getStarted')}
            </button>
          </div>
        </div>

        {/* Menu Mobile */}
        {mobileMenuOpen && (
          <div className="md:hidden py-4 border-t border-neutral-200 dark:border-neutral-800 animate-slide-up">
            <div className="flex flex-col space-y-2">
              {navItems.map((item) => (
                <a
                  key={item}
                  href={`#${item}`}
                  className="px-4 py-3 rounded-lg text-neutral-700 dark:text-neutral-300 hover:text-primary-600 dark:hover:text-primary-400 hover:bg-primary-50 dark:hover:bg-primary-900/30 transition-all duration-200 font-medium"
                  onClick={() => setMobileMenuOpen(false)}
                >
                  {t(item)}
                </a>
              ))}

              {/* Options de thème pour mobile */}
              <div className="pt-4 border-t border-neutral-200 dark:border-neutral-800">
                <div className="flex flex-col space-y-2">
                  <div className="px-4 py-2 text-sm font-medium text-neutral-500 dark:text-neutral-400">
                    {t('theme')}
                  </div>
                  <button
                    onClick={() => changeTheme('light')}
                    className="flex items-center space-x-3 px-4 py-2 rounded-lg hover:bg-primary-50 dark:hover:bg-primary-900/30 transition-colors"
                  >
                    <Sun size={18} className="text-neutral-600 dark:text-neutral-400" />
                    <span className="text-neutral-700 dark:text-neutral-300">{t('light')}</span>
                  </button>
                  <button
                    onClick={() => changeTheme('dark')}
                    className="flex items-center space-x-3 px-4 py-2 rounded-lg hover:bg-primary-50 dark:hover:bg-primary-900/30 transition-colors"
                  >
                    <Moon size={18} className="text-neutral-600 dark:text-neutral-400" />
                    <span className="text-neutral-700 dark:text-neutral-300">{t('dark')}</span>
                  </button>
                  <button
                    onClick={() => changeTheme('system')}
                    className="flex items-center space-x-3 px-4 py-2 rounded-lg hover:bg-primary-50 dark:hover:bg-primary-900/30 transition-colors"
                  >
                    <div className="flex items-center">
                      <Sun size={14} className="mr-[-2px] text-neutral-600 dark:text-neutral-400" />
                      <Moon size={14} className="ml-[-2px] text-neutral-600 dark:text-neutral-400" />
                    </div>
                    <span className="text-neutral-700 dark:text-neutral-300">{t('system')}</span>
                  </button>
                </div>
              </div>

              {/* Bouton CTA pour mobile */}
              <button className="mt-4 px-4 py-3 bg-gradient-to-r from-primary-500 to-secondary-500 hover:from-primary-600 hover:to-secondary-600 text-white font-medium rounded-lg transition-all duration-300">
                {t('getStarted')}
              </button>
            </div>
          </div>
        )}
      </div>
    </header>
  );
};

export default Header;
